def test_merge_configs_basic():
    result = merge_configs({"timeout": 30}, {"retries": 3})
    assert result == {"timeout": 30, "retries": 3}, f"словари должны объединиться без потерь: {result}"


def test_merge_configs_override():
    result = merge_configs({"timeout": 30, "retries": 3}, {"retries": 5})
    assert result == {"timeout": 30, "retries": 5}, "значение из более позднего словаря должно перезаписать предыдущее"


def test_merge_configs_no_args():
    assert merge_configs() == {}, "без аргументов должен вернуться пустой словарь"


def test_sort_by_duration():
    results = [{"name": "t1", "duration_ms": 300}, {"name": "t2", "duration_ms": 50}, {"name": "t3", "duration_ms": 120}]
    sorted_results = sort_by_duration(results)
    names = [r["name"] for r in sorted_results]
    assert names == ["t2", "t3", "t1"], f"результаты должны быть отсортированы по возрастанию duration_ms: {names}"
